        version: "1.0.0".to_string(),
        fields: vec![
            FieldSchema {
                name: "cores".to_string(),
                field_type: FieldType::Integer,
                required: true,
                description: Some("Number of CPU cores".to_string()),
                constraints: vec![],
                example: None,
                read_only: true,
